const body = $input.first().json;
if (!body.resume_text) throw new Error('resume_text is required');
return [{ json: {
  agent_input: `Extract all information from this resume and return ONLY valid JSON:\n\n${body.resume_text.substring(0, 4000)}\n\nJSON schema: {"personal_info":{"name":"","email":"","phone":"","location":""},"education":[{"institution":"","level":"","field":"","year":""}],"experience":[{"company":"","role":"","duration":"","responsibilities":[]}],"technical_skills":[],"certifications":[]}`,
  resume_text: body.resume_text,
  candidate_id: body.candidate_id || `cand_${Date.now()}`
} }];

const agentOutput = $input.first().json.output || '{}';
let extracted = {};
try {
  const cleaned = agentOutput.replace(/```json/g,'').replace(/```/g,'').trim();
  const m = cleaned.match(/(\{[\s\S]*\})/);
  extracted = JSON.parse(m ? m[1] : cleaned);
} catch(e) { extracted = { error: 'parse_failed', raw: agentOutput.substring(0, 500) }; }
return [{ json: {
  ...($node['Setup Input'].json),
  extraction_results: { structured_data: extracted, status: extracted.error ? 'partial' : 'completed' },
  agent_input: `Polish and standardize this candidate profile data. Return ONLY valid JSON: {"enhanced_summary":"","standardized_skills":[],"total_years_exp":0}\n\nInput data: ${JSON.stringify(extracted)}`
} }];

const agentOutput = $input.first().json.output || '{}';
const prev = $node['Parse ① + Prep ②'].json;
let enhanced = {};
try {
  const cleaned = agentOutput.replace(/```json/g,'').replace(/```/g,'').trim();
  const m = cleaned.match(/(\{[\s\S]*\})/);
  enhanced = JSON.parse(m ? m[1] : cleaned);
} catch(e) { enhanced = {}; }
const rawText = (prev.resume_text || '').substring(0, 2000);
return [{ json: {
  ...prev,
  enhanced_data: enhanced,
  agent_input: `Analyze this candidate and return ONLY valid JSON: {"technical_skills":[],"years_of_experience":0,"education":{"level":"","field":""},"experience_level":"Junior|Mid-level|Senior","key_achievements":[],"domain_expertise":[]}\n\nRaw resume: ${rawText}\nStructured data: ${JSON.stringify(prev.extraction_results?.structured_data || {})}\nEnhanced data: ${JSON.stringify(enhanced)}`
} }];

const agentOutput = $input.first().json.output || '{}';
const prev = $node['Parse ② + Prep ③'].json;
let skillsAnalysis = {};
try {
  const cleaned = agentOutput.replace(/```json/g,'').replace(/```/g,'').trim();
  const m = cleaned.match(/(\{[\s\S]*\})/);
  skillsAnalysis = JSON.parse(m ? m[1] : cleaned);
} catch(e) {
  skillsAnalysis = { technical_skills: [], years_of_experience: 0, education: {level:'Unknown',field:'Unknown'}, experience_level: 'Junior', key_achievements: [], domain_expertise: [] };
}
const skills = skillsAnalysis.technical_skills || [];
const role = `${skillsAnalysis.experience_level || 'Mid-level'} ${skills[0] || 'Software'} Developer`;
return [{ json: {
  ...prev,
  analysis_results: { skills_analysis: skillsAnalysis, analysis_timestamp: new Date().toISOString().split('T')[0], confidence_score: 0.85 },
  skills_for_matching: skills,
  exp_level: skillsAnalysis.experience_level || 'Mid-level',
  agent_input: `You are analyzing the job market RIGHT NOW in 2026. Generate 3 realistic, currently-available job listings for a '${role}' candidate who has these top skills: ${skills.slice(0,5).join(', ')}. Return ONLY valid JSON: {"market_jobs":[{"title":"","company":"","location":"","salary_range":"","requirements":[],"description":""}]}`
} }];

const agentOutput = $input.first().json.output || '{}';
const prev = $node['Parse ③ + Prep ④'].json;
const skills = prev.skills_for_matching || [];
const candidateSkills = new Set(skills.map(s => s.toLowerCase()));
let liveJobs = [];
try {
  const cleaned = agentOutput.replace(/```json/g,'').replace(/```/g,'').trim();
  const m = cleaned.match(/(\{[\s\S]*\})/);
  const parsed = JSON.parse(m ? m[1] : cleaned);
  liveJobs = parsed.market_jobs || [];
} catch(e) { liveJobs = []; }
const scoredJobs = liveJobs.map(job => {
  const reqs = Array.isArray(job.requirements) ? job.requirements : [];
  const reqSet = new Set(reqs.map(r => r.toLowerCase()));
  const overlap = [...reqSet].filter(r => candidateSkills.has(r)).length;
  const score = reqSet.size === 0 ? 75 : Math.round((overlap / reqSet.size) * 100);
  return { title: `${job.title} at ${job.company}`, match_score: score, location: job.location || 'Remote', salary_range: job.salary_range || 'Competitive', requirements: reqs, source: 'Live Market 🌐' };
}).filter(j => j.match_score >= 30).sort((a,b) => b.match_score - a.match_score);
const candidateName = prev.extraction_results?.structured_data?.personal_info?.name || 'Candidate';
const focusedCtx = JSON.stringify({ candidate_name: candidateName, skills_analysis: prev.analysis_results.skills_analysis, job_matches: scoredJobs.slice(0,3) });
return [{ json: {
  ...prev,
  job_matches: { matched_jobs: scoredJobs.slice(0,3), match_timestamp: new Date().toISOString().split('T')[0], number_of_matches: scoredJobs.length },
  agent_input: `Screen this candidate and return ONLY valid JSON (no markdown): {"screening_report":"3-4 sentence detailed report","screening_score":75,"red_flags":[]}\n\nCandidate data: ${focusedCtx}`
} }];

const agentOutput = $input.first().json.output || '{}';
const prev = $node['Score Jobs + Prep ⑤'].json;
let screening = {};
try {
  const cleaned = agentOutput.replace(/```json/g,'').replace(/```/g,'').trim();
  const m = cleaned.match(/(\{[\s\S]*\})/);
  screening = JSON.parse(m ? m[1] : cleaned);
} catch(e) { screening = { screening_report: 'Parse error', screening_score: 50, red_flags: [] }; }
const candidateName = prev.extraction_results?.structured_data?.personal_info?.name || 'Candidate';
const focusedCtx = JSON.stringify({
  candidate_name: candidateName,
  skills: prev.analysis_results?.skills_analysis?.technical_skills || [],
  experience: prev.analysis_results?.skills_analysis?.years_of_experience || 0,
  matches: prev.job_matches?.matched_jobs || [],
  screening_score: parseInt(screening.screening_score || 50),
  red_flags: screening.red_flags || []
});
return [{ json: {
  ...prev,
  screening_results: { screening_report: screening.screening_report || 'No report', screening_timestamp: new Date().toISOString(), screening_score: parseInt(screening.screening_score || 50), red_flags: screening.red_flags || [] },
  agent_input: `You are a Senior HR Director making a final hiring decision. Based on the candidate summary below, provide your recommendation. Return ONLY valid JSON: {"hiring_status":"Recommended|Not Recommended|Pending Review","recommendation":"2-3 sentence professional justification","next_steps":["step1","step2"],"confidence_level":"Low|Medium|High"}\n\nCandidate summary: ${focusedCtx}`
} }];

const agentOutput = $input.first().json.output || '{}';
const prev = $node['Parse ⑤ + Prep ⑥'].json;
let rec = {};
try {
  const cleaned = agentOutput.replace(/```json/g,'').replace(/```/g,'').trim();
  const m = cleaned.match(/(\{[\s\S]*\})/);
  rec = JSON.parse(m ? m[1] : cleaned);
} catch(e) { rec = { hiring_status: 'Pending Review', recommendation: 'Manual review required.', next_steps: [], confidence_level: 'Low' }; }
const { agent_input, resume_text, skills_for_matching, exp_level, ...clean } = prev;
return [{ json: { ...clean,
  final_recommendation: { hiring_status: rec.hiring_status || 'Pending Review', recommendation: rec.recommendation || 'Manual review required.', next_steps: rec.next_steps || [], recommendation_timestamp: new Date().toISOString(), confidence_level: rec.confidence_level || 'Medium' },
  status: 'completed'
} }];
